const crypto = require('crypto');
const input = $input.first().json;
const secret = $env.N8N_WEBHOOK_SECRET;
const timestamp = input.headers['x-webhook-timestamp'];
const signature = input.headers['x-webhook-signature'];
if (!secret || !/^[0-9a-f]{64}$/.test(signature || '')) throw new Error('Invalid signature');
const time = Date.parse(timestamp);
if (!Number.isFinite(time) || Math.abs(Date.now()-time)>300000) throw new Error('Expired timestamp');
const expected = crypto.createHmac('sha256', secret).update(timestamp + '.' + JSON.stringify(input.body)).digest('hex');
if (!crypto.timingSafeEqual(Buffer.from(expected,'hex'), Buffer.from(signature,'hex'))) throw new Error('Invalid signature');
if (!input.body.recipientPhone || !input.body.messageText || !input.body.dedupKey) throw new Error('Invalid notification');
return [{json:input.body}];
